from collections import deque

jobs = {"A": 8, "B": 4, "C": 1}  # name -> CPU burst (ms), all arrive at t=0

def run_in_order(order):
    t, wait = 0, {}
    for j in order:
        wait[j] = t
        t += jobs[j]
    return wait

def round_robin(quantum):
    remaining = dict(jobs)
    queue, t, done = deque(jobs), 0, {}
    while queue:
        j = queue.popleft()
        step = min(quantum, remaining[j])
        t += step
        remaining[j] -= step
        if remaining[j] == 0:
            done[j] = t
        else:
            queue.append(j)
    return {j: done[j] - jobs[j] for j in jobs}  # wait = finish - burst

for name, wait in [("FCFS", run_in_order("ABC")), ("SJF", run_in_order("CBA")), ("RR q=1", round_robin(1))]:
    print(f"{name:7} waits={wait}  avg={sum(wait.values()) / len(wait):.2f} ms")
